/**
 * Parses a value as a base-10 integer and clamps it between min and max (inclusive).
 * Returns fallback when the value does not parse to a valid integer.
 * Explicit zero (0 or '0') is treated as valid input, not as invalid.
 *
 * @param {unknown} value - The value to parse and clamp (string, number, etc.)
 * @param {number} fallback - The value to return when parsing fails
 * @param {number} min - The minimum allowed value (inclusive)
 * @param {number} max - The maximum allowed value (inclusive)
 * @returns {number} The clamped integer or fallback
 */
export function clampInteger(value, fallback, min, max) {
  // Handle explicit zero first - it's a valid integer
  if (value === 0 || value === '0') {
    return Math.max(min, Math.min(max, 0));
  }

  // Try to parse as integer
  const parsed = parseInt(value, 10);

  // Check if parsing resulted in a valid integer (NaN means invalid)
  if (Number.isNaN(parsed)) {
    return fallback;
  }

  // Clamp the value between min and max (inclusive)
  return Math.max(min, Math.min(max, parsed));
}
